Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public class RiskWindow { [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h,int n); [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr h,IntPtr after,int x,int y,int w,int h2,uint f); [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h); }'
$p=Get-Process -Name qemu-system-x86_64 | Where-Object {$_.MainWindowTitle -like '*Pleos_Connect_2_1*'} | Select-Object -First 1
if($p){[RiskWindow]::ShowWindow($p.MainWindowHandle,9)|Out-Null;[RiskWindow]::SetWindowPos($p.MainWindowHandle,[IntPtr](-1),35,35,1400,850,0x0040)|Out-Null;$ok=[RiskWindow]::SetForegroundWindow($p.MainWindowHandle);[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'window-status.txt'),"Desktop=Default; Foreground=$ok; Title=$($p.MainWindowTitle)")}